void ui_event_SaveButton(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        
        // 1. THU THẬP DỮ LIỆU MỚI TỪ UI VÀO BUFFER TẠM THỜI
        g_temp_override_event.device_levels[0] = (uint8_t)lv_slider_get_value(ui_LightSlider);
        g_temp_override_event.device_states[0] = lv_obj_has_state(ui_LightSwitch, LV_STATE_CHECKED);
        
        // ... (Thu thập tương tự cho SPRAYER, PUMPER, FAN Index 1, 2, 3)
        g_temp_override_event.device_levels[1] = (uint8_t)lv_slider_get_value(ui_SprayerSlider);
        g_temp_override_event.device_states[1] = lv_obj_has_state(ui_SprayerSwitch, LV_STATE_CHECKED);
        
        g_temp_override_event.device_levels[2] = (uint8_t)lv_slider_get_value(ui_PumperSlider);
        g_temp_override_event.device_states[2] = lv_obj_has_state(ui_PumperSwitch, LV_STATE_CHECKED);

        g_temp_override_event.device_levels[3] = (uint8_t)lv_slider_get_value(ui_FanSlider);
        g_temp_override_event.device_states[3] = lv_obj_has_state(ui_FanSwitch, LV_STATE_CHECKED);

        
        // 2. KIỂM TRA ĐIỀU KIỆN CẢNH BÁO
        if (g_is_event_running && g_active_scheduler_index != -1) {
            // Có Event đang chạy và cần cảnh báo ghi đè
            
            // Cập nhật Label cảnh báo
            if (g_active_scheduler_index < event_count) {
                 char msg[200];
                 // Lấy tên event đang bị ghi đè
                 sprintf(msg, "Do you really want to disable\nevent '%s' and apply manual settings?", 
                         event_list[g_active_scheduler_index].label);
                 lv_label_set_text(ui_WarningLabel1, msg);
            }
            
            // Hiện Panel cảnh báo
            _ui_flag_modify(ui_WarningPanel1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        } else {
            // Không có Event Scheduler nào đang chạy, chỉ cần áp dụng thay đổi thủ công.
            Serial.println("Manual states applied without override warning.");
            // Chuyển sang hàm YesButton logic để áp dụng g_temp_override_event cho g_current_active_event
            ui_event_YesButton1(e); 
        }
    }
}

void ui_event_YesButton1(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        
        // 1. Ghi đè g_current_active_event bằng giá trị mới từ g_temp_override_event
        if (xSemaphoreTake(g_event_mutex, pdMS_TO_TICKS(100)) == pdTRUE) {
            // Sao chép toàn bộ trạng thái thiết bị mới
            memcpy(&g_current_active_event.device_states, &g_temp_override_event.device_states, sizeof(g_current_active_event.device_states));
            memcpy(&g_current_active_event.device_levels, &g_temp_override_event.device_levels, sizeof(g_current_active_event.device_levels));
            
            // 2. DISABLE EVENT GỐC trong event_list
            if (g_is_event_running && g_active_scheduler_index != -1 && g_active_scheduler_index < event_count) {
                
                // Đặt Event gốc thành Disable
                event_list[g_active_scheduler_index].is_enabled = false;
                
                // Lưu lại danh sách Event vào NVS
                if (save_event_list()) {
                     Serial.printf("SUCCESS: Disabled scheduled event at index %d due to manual override.\n", g_active_scheduler_index);
                } else {
                     Serial.println("ERROR: Failed to save event list after disabling scheduled event.");
                }
            }
            
            // Đặt cờ Event running thành FALSE (để biết đã bị override)
            g_is_event_running = false; 
            g_active_scheduler_index = -1; // Reset index đã bị disable

            xSemaphoreGive(g_event_mutex);
            sync_all_attributes_to_server(); // Đồng bộ trạng thái mới lên server
        }
        
        // 3. Ẩn Panel cảnh báo
        _ui_flag_modify(ui_WarningPanel1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        
        // LƯU Ý: Task HardwareControlTask sẽ tự động nhận giá trị mới từ g_current_active_event và điều khiển thiết bị.
    }
}

