void update_screen2_ui() {
    // 1. Kiểm tra Mutex trước khi đọc g_current_active_event
    if (xSemaphoreTake(g_event_mutex, pdMS_TO_TICKS(10)) == pdTRUE) {
        
        // 2. Cập nhật Event/Time Label (On Going Event)
        if (g_is_event_running) {
            lv_label_set_text(ui_OnGoingEvent, "On going event:");
            lv_label_set_text(ui_Event, g_current_active_event.label);
            
            char from_time[6], to_time[6];
            sprintf(from_time, "%02d:%02d", g_current_active_event.start_hour, g_current_active_event.start_minute);
            sprintf(to_time, "%02d:%02d", g_current_active_event.end_hour, g_current_active_event.end_minute);
            
            lv_label_set_text(ui_FromTime, from_time);
            lv_label_set_text(ui_ToTime, to_time);
            
            // 3. Cập nhật trạng thái và Slider của thiết bị
            // Ánh xạ g_current_active_event -> UI Widgets
            
            

            // Hiển thị Warning Panel khi Save
            // _ui_flag_modify(ui_WarningPanel1, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
            
        } else {
            // Không có Event nào chạy -> Reset UI về mặc định
            lv_label_set_text(ui_OnGoingEvent, "No event running");
            lv_label_set_text(ui_Event, "");
            lv_label_set_text(ui_FromTime, "");
            lv_label_set_text(ui_ToTime, "");
        }
        // LIGHT (Index 0)
            lv_slider_set_value(ui_LightSlider, g_current_active_event.device_levels[0], LV_ANIM_OFF);
            if (g_current_active_event.device_states[0]) lv_obj_add_state(ui_LightSwitch, LV_STATE_CHECKED);
            else lv_obj_clear_state(ui_LightSwitch, LV_STATE_CHECKED);

            // SPRAYER (Index 1)
            lv_slider_set_value(ui_SprayerSlider, g_current_active_event.device_levels[1], LV_ANIM_OFF);
            if (g_current_active_event.device_states[1]) lv_obj_add_state(ui_SprayerSwitch, LV_STATE_CHECKED);
            else lv_obj_clear_state(ui_SprayerSwitch, LV_STATE_CHECKED);
            
            // PUMPER (Index 2)
            lv_slider_set_value(ui_PumperSlider, g_current_active_event.device_levels[2], LV_ANIM_OFF);
            if (g_current_active_event.device_states[2]) lv_obj_add_state(ui_PumperSwitch, LV_STATE_CHECKED);
            else lv_obj_clear_state(ui_PumperSwitch, LV_STATE_CHECKED);
            
            // FAN (Index 3)
            lv_slider_set_value(ui_FanSlider, g_current_active_event.device_levels[3], LV_ANIM_OFF);
            if (g_current_active_event.device_states[3]) lv_obj_add_state(ui_FanSwitch, LV_STATE_CHECKED);
            else lv_obj_clear_state(ui_FanSwitch, LV_STATE_CHECKED);
        xSemaphoreGive(g_event_mutex);
    } else {
        Serial.println("ERROR: Could not take Mutex in update_screen2_ui!");
    }
}

void ui_event_Screen2_Load(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if (event_code == LV_EVENT_SCREEN_LOAD_START) {
        update_screen2_ui(); 
    }
}
