void ui_event_Calendar3(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    if(event_code == LV_EVENT_CLICKED) {
        lv_calendar_date_t pressed_date;
        
        // 1. Cố gắng lấy ngày được chọn từ Calendar
        if (lv_calendar_get_pressed_date(ui_Calendar3, &pressed_date) == LV_RES_OK) {
            //2. Lưu ngày vào biến toàn cục g_selected_date
            g_selected_date.year = pressed_date.year;
            g_selected_date.month = pressed_date.month;
            g_selected_date.day = pressed_date.day;
            
            // Đánh dấu không phải là chỉnh sửa Event
            g_event_edit_index = -1;
            
            // 3. Chuyển sang Screen 7 (Danh sách Event)
             _ui_screen_change(&ui_Screen7, LV_SCR_LOAD_ANIM_FADE_ON, 200, 0, &ui_Screen7_screen_init);
        }
    }
}
