int get_day_of_week(uint16_t year, uint8_t month, uint8_t day) {
    struct tm t = {0};
    t.tm_year = year - 1900;
    t.tm_mon = month - 1;
    t.tm_mday = day;
    // Gọi hàm mktime để tính tm_wday (ngày trong tuần)
    mktime(&t); 
    // tm_wday: 0=CN, 1=T2, ..., 6=T7
    return t.tm_wday; 
}
const char* get_day_name(int dow) {
    // DOW: 0=CN, 1=T2, ..., 6=T7 (theo POSIX)
    switch (dow) {
        case 0: return "Sunday";
        case 1: return "Monday";
        case 2: return "Tuesday";
        case 3: return "Wednesday";
        case 4: return "Thursday";
        case 5: return "Friday";
        case 6: return "Saturday";
        default: return "";
    }
}
const char* get_day_name_top_bar(int dow) {
    // DOW: 0=CN, 1=T2, ..., 6=T7 (theo POSIX)
    switch (dow) {
        case 0: return "Sun";
        case 1: return "Mon";
        case 2: return "Tue";
        case 3: return "Wed";
        case 4: return "Thu";
        case 5: return "Fri";
        case 6: return "Sat";
        default: return "";
    }
}

const char* get_month_name_top_bar(int month) {
    // Tháng được truyền vào thường là 1 (Jan) đến 12 (Dec)
    switch (month) {
        case 1: return "JAN";
        case 2: return "FEB";
        case 3: return "MAR";
        case 4: return "APR";
        case 5: return "MAY";
        case 6: return "JUN";
        case 7: return "JUL";
        case 8: return "AUG";
        case 9: return "SEP";
        case 10: return "OCT";
        case 11: return "NOV";
        case 12: return "DEC";
        default: return ""; // Trả về chuỗi rỗng nếu tháng không hợp lệ
    }
}

bool is_event_active_on_selected_date(const scheduler_event_t *event, const selected_date_t *selected_date) {
    if (event->year == selected_date->year &&
        event->month == selected_date->month &&
        event->day == selected_date->day) 
    {
        return true;
    }

    // --- Trường hợp 1: Event Lặp lại Hàng tuần (Weekly Repeat) ---
    if (event->repeat_weekly) {
        
        // 1. Lấy ngày trong tuần (DOW) của Event đã lưu (Ngày Event được tạo/lưu)
        // Đây là DOW mà Event cần lặp lại hàng tuần.
        int event_dow = get_day_of_week(event->year, event->month, event->day);
        
        // 2. Lấy ngày trong tuần (DOW) của Ngày được chọn trên lịch
        int selected_dow = get_day_of_week(selected_date->year, selected_date->month, selected_date->day);
        
        // 3. Kiểm tra xem hai ngày trong tuần có trùng nhau không
        if (event_dow == selected_dow) {
            return true;
        }
        
        return false;
    } 

    // --- Trường hợp 2: Event Một lần (Single Event) ---
    
    // Kiểm tra chính xác ngày, tháng, năm đã lưu trong Event struct
    

    return false; // Không khớp
}
void update_screen7_event_list() {
    // 1. Tải Event List mới nhất từ NVS
    load_event_list(); 
    //setup_event_panels_array();
    
    // 2. Cập nhật ngày hiển thị trên Screen 7
    char date_str[100];
    int dow = get_day_of_week(g_selected_date.year, g_selected_date.month, g_selected_date.day);
    const char* day_name = get_day_name(dow);

// Định dạng chuỗi mới: "Events on Thứ X, DD/MM/YYYY"
sprintf(date_str, "Events on %s, %02d/%02d/%04d", 
        day_name, 
        g_selected_date.day, 
        g_selected_date.month, 
        g_selected_date.year);
    lv_label_set_text(ui_DateEventsLabel, date_str);
    
    for (size_t i = 0; i < MAX_VISIBLE_EVENTS; i++) {
        _ui_flag_modify(g_event_panels[i], LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        if (g_event_switches[i] != NULL) {
             // CLEAR trạng thái switch để tránh lỗi "switch stuck ON"
            lv_obj_clear_state(g_event_switches[i], LV_STATE_CHECKED);
        }
    }

    int visible_events_count = 0;
    
    //3. Duyệt qua danh sách Event và cập nhật Panel //event_count && visible_events_count < MAX_VISIBLE_EVENTS
    for (size_t i = 0; i < event_count && visible_events_count < MAX_VISIBLE_EVENTS; i++) {
         scheduler_event_t * current_event = &event_list[i];
        
    //     // // --- LOGIC LỌC TẠM THỜI ---
    //     // // Hiện tại, chúng ta bỏ qua lọc theo ngày. Sau này, bạn cần thêm logic kiểm tra xem
    //     // // Event này có trùng với g_selected_date không (dựa trên repeat_weekly hoặc ngày cụ thể).
    //     // // Tạm thời, chỉ hiển thị tất cả Event đã lưu.
        if (!is_event_active_on_selected_date(current_event, &g_selected_date)) {
            continue; // Bỏ qua Event này nếu nó không hoạt động vào ngày đã chọn
        }
         lv_obj_t * event_panel = g_event_panels[visible_events_count];
        
    //     // // Hiện Panel
         _ui_flag_modify(event_panel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    //     // a. Tên Event
         lv_label_set_text(g_event_labels[visible_events_count], current_event->label);
        
    //     // b. Thời gian Event
          char time_range[16];
          sprintf(time_range, "%02d:%02d - %02d:%02d", 
            current_event->start_hour, current_event->start_minute, 
             current_event->end_hour, current_event->end_minute);
          lv_label_set_text(g_time_labels[visible_events_count], time_range);
        
    //     // c. Trạng thái Switch (Bật/Tắt Event)
          if (current_event->is_enabled) {
              lv_obj_add_state(g_event_switches[visible_events_count], LV_STATE_CHECKED);
          } else {
              lv_obj_clear_state(g_event_switches[visible_events_count], LV_STATE_CHECKED);
          }
        
    //     // d. Lưu Event Index vào User Data của các nút và Switch
        //Việc này giúp chúng ta biết Event nào đang được thao tác khi nhấn nút.
        lv_obj_set_user_data(g_config_buttons[visible_events_count], (void*)i);
        lv_obj_set_user_data(g_delete_buttons[visible_events_count], (void*)i);
        lv_obj_set_user_data(g_seen_buttons[visible_events_count], (void*)i);
         lv_obj_set_user_data(g_event_switches[visible_events_count], (void*)i);

         visible_events_count++;
    }
    
    //4. Ẩn các Panel Event còn lại
    // for (size_t i = visible_events_count; i < MAX_VISIBLE_EVENTS; i++) {
    //     _ui_flag_modify(g_event_panels[i], LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
    // }
}

