void update_screen8_editor() {
    if (g_event_edit_index >= 0 && g_event_edit_index < event_count) {
        // --- CHẾ ĐỘ CHỈNH SỬA (EDIT) ---
        scheduler_event_t * current_event = &event_list[g_event_edit_index];
        lv_label_set_text(ui_EventLabel, "Label:"); 
        
        // 1. Tên và Checkbox
        lv_textarea_set_text(ui_EventText, current_event->label);
        if (current_event->repeat_weekly) lv_obj_add_state(ui_Checkbox1, LV_STATE_CHECKED);
        else lv_obj_clear_state(ui_Checkbox1, LV_STATE_CHECKED);

        // 2. Thời gian
        lv_roller_set_selected(ui_FromRollerHour, current_event->start_hour, LV_ANIM_OFF);
        lv_roller_set_selected(ui_FromRollerMinute, current_event->start_minute, LV_ANIM_OFF);
        lv_roller_set_selected(ui_ToRollerHour, current_event->end_hour, LV_ANIM_OFF);
        lv_roller_set_selected(ui_ToRollerMinute, current_event->end_minute, LV_ANIM_OFF);

        // 3. Thiết bị (Lấy 4 thiết bị: 0=LIGHT, 1=SPRAYER, 2=PUMP, 3=FAN)
        lv_slider_set_value(ui_LightSliderSche, current_event->device_levels[0], LV_ANIM_OFF);
        if (current_event->device_states[0]) lv_obj_add_state(ui_LightSwitchSche, LV_STATE_CHECKED);
        else lv_obj_clear_state(ui_LightSwitchSche, LV_STATE_CHECKED);
        
        lv_slider_set_value(ui_SprayerSliderSche, current_event->device_levels[1], LV_ANIM_OFF);
        if (current_event->device_states[1]) lv_obj_add_state(ui_SprayerSwitchSche, LV_STATE_CHECKED);
        else lv_obj_clear_state(ui_SprayerSwitchSche, LV_STATE_CHECKED);
        
        lv_slider_set_value(ui_PumperSliderSche, current_event->device_levels[2], LV_ANIM_OFF); 
        if (current_event->device_states[2]) lv_obj_add_state(ui_PumperSwitchSche, LV_STATE_CHECKED);
        else lv_obj_clear_state(ui_PumperSwitchSche, LV_STATE_CHECKED);
        
        lv_slider_set_value(ui_FanSliderSche, current_event->device_levels[3], LV_ANIM_OFF);
        if (current_event->device_states[3]) lv_obj_add_state(ui_FanSwitchSche, LV_STATE_CHECKED);
        else lv_obj_clear_state(ui_FanSwitchSche, LV_STATE_CHECKED);

    } else {
        // --- CHẾ ĐỘ THÊM MỚI (NEW) ---
        lv_label_set_text(ui_EventLabel, "Label:");
        
        // Đặt giá trị mặc định/reset
        lv_textarea_set_text(ui_EventText, "");
        lv_roller_set_selected(ui_FromRollerHour, 0, LV_ANIM_OFF);
        lv_roller_set_selected(ui_FromRollerMinute, 0, LV_ANIM_OFF);
        // ... (Đặt mặc định cho tất cả các widget khác)
        lv_slider_set_value(ui_LightSliderSche, 0, LV_ANIM_OFF);
        lv_obj_clear_state(ui_LightSwitchSche, LV_STATE_CHECKED);
        lv_obj_clear_state(ui_Checkbox1, LV_STATE_CHECKED); 
    }
    char date_str[100];
    
    // 1. Tính toán Thứ của ngày được chọn
    int dow = get_day_of_week(g_selected_date.year, g_selected_date.month, g_selected_date.day);
    const char* day_name = get_day_name(dow);
    
    // 2. Tạo chuỗi hoàn chỉnh: "Thứ X, Ngày/Tháng/Năm"
    sprintf(date_str, "%s %02d/%02d/%04d", 
            day_name, 
            g_selected_date.day, 
            g_selected_date.month, 
            g_selected_date.year);
    
    // 3. Gán chuỗi vào Label
    if (ui_Label100 != NULL) { 
        lv_label_set_text(ui_Label100, date_str);
    }
}
