void delete_event(int32_t index) {
    // Đảm bảo index hợp lệ
    if (index >= 0 && index < event_count) {
        // Di chuyển các phần tử sau index lên trước (logic xóa khỏi mảng)
        for (size_t i = index; i < event_count - 1; i++) {
            event_list[i] = event_list[i + 1];
        }
        event_count--;
        save_event_list(); // Lưu NVS
        Serial.printf("Event at index %d deleted: %s\n", index, event_list[index].label);
    }
}

// --- LOGIC CHUYỂN SCREEN VÀ XỬ LÝ DỮ LIỆU ---

// 1. Chuyển sang Screen 8 EDIT (Config/Seen Button)
void ui_event_ConfigEvent_Handler(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    if(event_code == LV_EVENT_CLICKED) {
        // Lấy Event Index đã được lưu trong user_data của nút
        g_event_edit_index = (int32_t)lv_obj_get_user_data(target);
        
        // Chuyển sang Screen 8 (sẽ tải dữ liệu cũ lên do g_event_edit_index >= 0)
        _ui_screen_change(&ui_Screen8, LV_SCR_LOAD_ANIM_FADE_ON, 500, 0, &ui_Screen8_screen_init);
    }
}

// 2. Chuyển sang Screen 8 NEW (Add Button)
void ui_event_AddButton_New(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        size_t current_active_count = count_active_events_for_date();
        
        // 2. Kiểm tra nếu đã đạt đến giới hạn hiển thị tối đa (MAX_VISIBLE_EVENTS)
        // Chúng ta sử dụng MAX_VISIBLE_EVENTS (ví dụ: 10) làm giới hạn hợp lý cho UI
        if (current_active_count >= MAX_VISIBLE_EVENTS) {
            
            // HIỂN THỊ CẢNH BÁO MAX EVENT
            
            // Giả định Panel cảnh báo là ui_MaxWarningPanel
            if (ui_MaxWarningPanel != NULL) { 
                 _ui_flag_modify(ui_MaxWarningPanel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
                 // Bạn có thể thêm logic cập nhật Label cảnh báo tại đây
                 Serial.println("WARNING: Cannot add more events. Max visible limit reached.");
            } else {
                 Serial.println("ERROR: ui_MaxWarningPanel is NULL.");
            }
            
            // Không chuyển màn hình (END FUNCTION)
            return; 
        } 
        
        // 3. Nếu chưa đạt giới hạn, tiến hành chuyển sang Screen 8 (ADD NEW)
        g_event_edit_index = -1; // Đánh dấu là Thêm mới
        _ui_screen_change(&ui_Screen8, LV_SCR_LOAD_ANIM_FADE_ON, 500, 0, &ui_Screen8_screen_init);
    }
}

// 3. Toggle Switch (Bật/Tắt Event)
void ui_event_EventSwitch_Toggle(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    // Sử dụng LV_EVENT_VALUE_CHANGED vì đây là Switch
    if(event_code == LV_EVENT_VALUE_CHANGED) {
        // Lấy Event Index đã được lưu trong user_data của switch
        int32_t event_index = (int32_t)lv_obj_get_user_data(target);
        
        if (event_index >= 0 && event_index < event_count) {
            bool state = lv_obj_has_state(target, LV_STATE_CHECKED);
            
            // Cập nhật trạng thái và lưu NVS
            event_list[event_index].is_enabled = state;
            save_event_list();
            
            Serial.printf("Event %s toggled to %s\n", event_list[event_index].label, state ? "ON" : "OFF");
        }
    }
}

// --- LOGIC XÁC NHẬN XÓA (Warning Panel) ---

// 4. Nút Delete (Hiện Warning Panel)
void ui_event_DeleteEvent_Handler(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    if(event_code == LV_EVENT_CLICKED) {
        // 1. Lấy Index Event từ User Data của nút
        int32_t index_to_delete = (int32_t)lv_obj_get_user_data(target);
        
        // 2. Lưu index vào biến toàn cục cho hàm xác nhận
        g_event_edit_index = index_to_delete; 
        
        // 3. Cập nhật Label xác nhận
        if (g_event_edit_index != -1 && g_event_edit_index < event_count) {
             char msg[100];
             sprintf(msg, "Do you want\n to delete event: %s?", event_list[index_to_delete].label);
             lv_label_set_text(ui_WarningLabel, msg);
        }
        // 4. Hiện Warning Panel
        _ui_flag_modify(ui_WarningPanel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
}

// 5. Nút YES (Thực hiện xóa)
void ui_event_YesButton_Delete(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        if (g_event_edit_index != -1) {
            delete_event(g_event_edit_index); // Xóa Event và lưu NVS
            g_event_edit_index = -1; // Reset index
        }
        _ui_flag_modify(ui_WarningPanel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        update_screen7_event_list(); // Cập nhật lại danh sách trên UI
    }
}

// 6. Nút NO (Hủy xóa)
void ui_event_NoButton_Delete(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        _ui_flag_modify(ui_WarningPanel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        g_event_edit_index = -1; // Reset index
    }
}